// 1. Get FULL state
let state;
try {
  state = { ...$('Update Text State').last().json };
} catch (e) {
  state = { ...$('Set Brand Context').first().json };
}

// 2. Get LLM response
const response = $input.first().json;
let content = response?.choices?.[0]?.message?.content || '{}';
content = content.replace(/```json|```/g, "").trim();

if (content.startsWith('"') && content.endsWith('"')) {
  try { content = JSON.parse(content); } catch (e) {}
}

let parsed;
try {
  parsed = typeof content === "string" ? JSON.parse(content) : content;
} catch (e) {
  parsed = {};
}

// 3. Extract posts
state.linkedin_post = (parsed.linkedin_post || "").trim();
state.facebook_post = (parsed.facebook_post || "").trim();
state.instagram_post = (parsed.instagram_post || "").trim();
state.reddit_post = (parsed.reddit_post || "").trim();
state.twitter_post = (parsed.twitter_post || "").trim();

// 4. Extract titles & tags
state.title_default = (parsed.title_default || "").trim();
state.title_reddit = (parsed.title_reddit || "").trim();
if (Array.isArray(parsed.tags)) {
  state.tags = parsed.tags.map(tag => String(tag).toLowerCase().trim());
} else {
  state.tags = [];
}

// 5. Clean titles from posts
if (state.title_default) {
  state.linkedin_post = state.linkedin_post.replace(state.title_default, "").trim();
  state.facebook_post = state.facebook_post.replace(state.title_default, "").trim();
  state.instagram_post = state.instagram_post.replace(state.title_default, "").trim();
}
if (state.title_reddit) {
  state.reddit_post = state.reddit_post.replace(state.title_reddit, "").trim();
}

// 6. Strict Platform filtering
const platforms = state.platforms || [];
const has = (p) => platforms.includes(p);
if (!has('linkedin')) state.linkedin_post = '';
if (!has('facebook')) state.facebook_post = '';
if (!has('instagram')) state.instagram_post = '';
if (!has('reddit')) state.reddit_post = '';
if (!has('twitter')) state.twitter_post = '';

// 7. Retries
state.retries_left = state.retries_left !== undefined ? Number(state.retries_left) : 3;
state.image_retries_left = state.image_retries_left !== undefined ? Number(state.image_retries_left) : 3;

return [{ json: state }];

