      brand_colors: Array.isArray(brandData.brand_colors) ? brandData.brand_colors : [],
      brand_style: brandData.brand_style || "",
      brand_text: brandData.brand_text || "",
      logo_url: brandData.logo_url || "",
      logo_position: brandData.logo_position || "top-right"
    }
  : defaultBrand;

state.brand = brand;
return [{ json: state }];

const referenceImageUrl = $input.first().json.reference_image_url || '';
const payload = {
  model: "meta-llama/llama-4-scout-17b-16e-instruct",
  messages: [
    {
      role: "system",
      content: `Extract structured insights to generate a NEW image with same style. Return ONLY JSON.`
    },
    {
      role: "user",
      content: [
        { type: "text", text: `Analyze this image...` },
        { type: "image_url", image_url: { url: referenceImageUrl } }
      ]
    }
  ],
  temperature: 0.2,
  response_format: { type: "json_object" }
};

return [{ json: { ...$input.first().json, groq_body: payload } }];

const baseState = $("Reset Image State").first().json;
const incomingItems = $input.all();
let state = { ...baseState };

for (const item of incomingItems) {
  const data = item.json || {};
  if (data.reference_analysis && typeof data.reference_analysis === 'object') state.reference_analysis = data.reference_analysis;
  if (data.image_prompt_current) state.image_prompt_current = data.image_prompt_current;
  if (data.image_url) state.image_url = data.image_url;
}

state.brand = state.brand || {};
state.brand.brand_colors = Array.isArray(state.brand.brand_colors) ? state.brand.brand_colors : [];

const fieldsToEnsure = [
  'topic', 'tone', 'context', 'post_details', 
  'linkedin_post', 'facebook_post', 'instagram_post', 'reddit_post', 'twitter_post',
  'image_prompt_current', 'image_url', 'reference_image_url'
];

fieldsToEnsure.forEach(field => { state[field] = state[field] || ""; });

return [{ json: state }];

